public List<Member> searchJpql(String username, Integer minAge) {
    StringBuilder jpql = new StringBuilder("select m from Member m where 1=1");
    Map<String, Object> params = new HashMap<>();
    if (username != null) {
        jpql.append(" and m.username = :username");
        params.put("username", username);
    }
    if (minAge != null) {
        jpql.append(" and m.age >= :minAge");
        params.put("minAge", minAge);
    }
    TypedQuery<Member> q = em.createQuery(jpql.toString(), Member.class);
    params.forEach(q::setParameter);
    return q.getResultList();
}

public List<Member> search(String username, Integer minAge) {
    return queryFactory.selectFrom(member)
            .where(usernameEq(username), ageGoe(minAge))
            .fetch();
}

